{"content": "     1|import 'reflect-metadata';
     2|import { NestFactory } from '@nestjs/core';
     3|import * as trpcExpress from '@trpc/server/adapters/express';
     4|import rateLimit from 'express-rate-limit';
     5|import { AppModule } from './app.module';
     6|import { appRouter } from './trpc';
     7|import { createContext } from './trpc/context';
     8|import { AnalyticsService } from './modules/analytics/analytics.service';
     9|import { assertRequiredEnv, env } from './lib/env';
    10|import { getRedis } from './lib/redis';
    11|import { WechatPayAdapter } from './adapters/wechat-pay.adapter';
    12|import { AlipayAdapter } from './adapters/alipay.adapter';
    13|import { PaymentService } from './modules/payment/payment.service';
    14|import { logger } from './lib/logger';
    15|import { prisma } from './lib/prisma';
    16|import { startRecallJob } from './jobs/recall.job';
    17|
    18|async function bootstrap() {
    19|  assertRequiredEnv();
    20|
    21|  const app = await NestFactory.create(AppModule, { logger: ['error', 'warn', 'log'] });
    22|
    23|  // CORS — restrict in production
    24|  app.enableCors({
    25|    origin: env.CORS_ORIGINS,
    26|    credentials: true,
    27|  });
    28|
    29|  // Rate limiting
    30|  app.use(rateLimit({
    31|    windowMs: 15 * 60 * 1000, // 15 minutes
    32|    max: 100, // limit each IP
    33|    standardHeaders: true,
    34|    legacyHeaders: false,
    35|    message: { error: '请求过于频繁，请稍后再试' },
    36|  }));
    37|
    38|  // Stricter rate limit for auth endpoints
    39|  app.use('/trpc/auth.sendCode', rateLimit({
    40|    windowMs: 60 * 1000,
    41|    max: 3,
    42|    message: { error: '验证码发送过于频繁' },
    43|  }));
    44|
    45|  // Health check — pings database; Railway uses this for healthcheck
    46|  app.use('/health', async (_req: any, res: any) => {
    47|    const startTime = Date.now();
    48|    let dbOk = false;
    49|    let redisOk = false;
    50|
    51|    await Promise.all([
    52|      prisma.$queryRaw`SELECT 1`.then(() => { dbOk = true; }).catch(() => {}),
    53|      (async () => {
    54|        const redis = getRedis();
    55|        if (redis) {
    56|          try { await redis.ping(); redisOk = true; } catch {}
    57|        }
    58|      })(),
    59|    ]);
    60|
    61|    res.json({
    62|      status: dbOk ? 'ok' : 'degraded',
    63|      timestamp: new Date().toISOString(),
    64|      checks: { db: dbOk, redis: redisOk },
    65|      uptime_ms: process.uptime() * 1000,
    66|      response_ms: Date.now() - startTime,
    67|      env: process.env.NODE_ENV ?? 'unknown',
    68|    });
    69|  });
    70|
    71|  // Analytics event ingestion (high-throughput, no auth required)
    72|  const expressApp = app.getHttpAdapter().getInstance();
    73|  expressApp.use('/analytics/events', require('express').json({ limit: '100kb' }));
    74|  expressApp.post('/analytics/events', (req: any, res: any) => {
    75|    const { events } = req.body;
    76|    if (!Array.isArray(events)) {
    77|      return res.status(400).json({ error: 'events must be an array' });
    78|    }
    79|    AnalyticsService.ingest(events);
    80|    res.json({ accepted: events.length });
    81|  });
    82|
    83|  // Dev-only file upload receiver — uses local filesystem which doesn't
    84|  // work on ephemeral containers (Railway, K8s). Only enable when explicitly
    85|  // NODE_ENV=development. preview/staging/production use OSS adapter instead.
    86|  //
    87|  // Also: Express 5 / path-to-regexp 8 dropped the `:param(*)` syntax, so the
    88|  // wildcard file-serve route uses a regex instead.
    89|  if (env.NODE_ENV === 'development') {
    90|    const fs = await import('node:fs/promises');
    91|    const path = await import('node:path');
    92|    const express = require('express');
    93|    const uploadDir = path.join(process.cwd(), '.uploads');
    94|    await fs.mkdir(uploadDir, { recursive: true });
    95|
    96|    // Receive uploaded file
    97|    expressApp.use('/upload/receive', express.raw({ type: '*/*', limit: '50mb' }));
    98|    expressApp.put('/upload/receive', async (req: any, res: any) => {
    99|      const key = req.query.key as string;
   100|      if (!key) return res.status(400).json({ error: 'Missing key' });
   101|      const filePath = path.join(uploadDir, key);
   102|      await fs.mkdir(path.dirname(filePath), { recursive: true });
   103|      await fs.writeFile(filePath, req.body);
   104|      res.json({ success: true, key });
   105|    });
   106|
   107|    // Serve uploaded files (wildcard via regex — Express 5 compatible)
   108|    expressApp.get(/^\/upload\/files\/(.+)$/, async (req: any, res: any) => {
   109|      const key = req.params[0];
   110|      const filePath = path.join(uploadDir, key);
   111|      try {
   112|        const data = await fs.readFile(filePath);
   113|        res.set('Content-Type', 'image/jpeg'); // rough default
   114|        res.set('Cache-Control', 'public, max-age=86400');
   115|        res.send(data);
   116|      } catch {
   117|        res.status(404).json({ error: 'Not found' });
   118|      }
   119|    });
   120|  }
   121|
   122|  // Payment callbacks (must be registered before tRPC mount)
   123|  const expressLib = require('express');
   124|
   125|  // WeChat Pay v3 webhook — raw body needed for signature verify
   126|  expressApp.post(
   127|    '/webhooks/wechat-pay',
   128|    expressLib.raw({ type: '*/*' }),
   129|    async (req: any, res: any) => {
   130|      const body = req.body?.toString('utf8') || '';
   131|      const headers = req.headers as Record<string, string>;
   132|
   133|      if (!WechatPayAdapter.verifyCallback(headers, body)) {
   134|        return res.status(401).json({ code: 'FAIL', message: 'signature verify failed' });
   135|      }
   136|
   137|      try {
   138|        const payload = JSON.parse(body);
   139|        const decrypted = WechatPayAdapter.decryptCallback(payload.resource);
   140|        if (decrypted?.trade_state === 'SUCCESS') {
   141|          await PaymentService.markOrderPaid(
   142|            decrypted.out_trade_no,
   143|            decrypted.transaction_id,
   144|          );
   145|        }
   146|        res.json({ code: 'SUCCESS', message: 'OK' });
   147|      } catch (err: any) {
   148|        logger.error('wechat callback error', { error: err?.message });
   149|        res.status(500).json({ code: 'FAIL', message: err?.message });
   150|      }
   151|    },
   152|  );
   153|
   154|  // Alipay webhook — form-urlencoded
   155|  expressApp.use('/webhooks/alipay', expressLib.urlencoded({ extended: false }));
   156|  expressApp.post('/webhooks/alipay', async (req: any, res: any) => {
   157|    const params = req.body as Record<string, string>;
   158|    if (!AlipayAdapter.verifyCallback(params)) {
   159|      return res.send('fail');
   160|    }
   161|    if (
   162|      params.trade_status === 'TRADE_SUCCESS' ||
   163|      params.trade_status === 'TRADE_FINISHED'
   164|    ) {
   165|      await PaymentService.markOrderPaid(params.out_trade_no, params.trade_no);
   166|    }
   167|    res.send('success');
   168|  });
   169|
   170|  // Mount tRPC
   171|  app.use('/trpc', trpcExpress.createExpressMiddleware({
   172|    router: appRouter,
   173|    createContext,
   174|  }));
   175|
   176|  const port = env.PORT;
   177|  // Bind to 0.0.0.0 so Railway / Docker edge proxies can reach the server.
   178|  // Default 'localhost' binding only accepts requests from inside the container.
   179|  await app.listen(port, '0.0.0.0');
   180|  AnalyticsService.startAutoFlush();
   181|  startRecallJob();
   182|  logger.info('server started', { port, env: env.NODE_ENV });
   183|}
   184|
   185|void bootstrap();
   186|
